import {mkdir,readFile,writeFile,rename,appendFile} from 'node:fs/promises';
import {join} from 'node:path';
import {randomUUID} from 'node:crypto';
import {setTimeout as wait} from 'node:timers/promises';
export function currentTime(timeZone=Intl.DateTimeFormat().resolvedOptions().timeZone){const date=new Date();return {timeZone,local:new Intl.DateTimeFormat('zh-CN',{timeZone,dateStyle:'full',timeStyle:'long'}).format(date),iso:date.toISOString(),unixMs:date.getTime()};}
export async function sleep(seconds,signal){if(!Number.isFinite(seconds)||seconds<0)throw Error('需要有效秒数');const until=Date.now()+seconds*1000;while(Date.now()<until)await wait(Math.min(60000,until-Date.now()),undefined,{signal});return currentTime();}
export class MusicSession {
 constructor(root){this.root=root;this.memory={preferences:[],listening:[]};this.timers=new Map();this.mode='off';this.owner=null;this.track=null;this.writes=Promise.resolve();}
 async load(){try{this.memory=JSON.parse(await readFile(join(this.root,'music-memory.json'),'utf8'));}catch(e){if(e.code!=='ENOENT')throw e;}return this;}
 async save(){const text=JSON.stringify(this.memory,null,2);this.writes=this.writes.catch(()=>{}).then(async()=>{await mkdir(this.root,{recursive:true});const path=join(this.root,'music-memory.json');await writeFile(path+'.tmp',text);await rename(path+'.tmp',path);});return this.writes;}
 async remember(action,args={}){if(action==='read')return this.memory;if(action==='preference'){if(!args.note?.trim())throw Error('需要偏好文字');if(!this.memory.preferences.includes(args.note))this.memory.preferences.push(args.note);}else if(action==='forget_preference')this.memory.preferences=this.memory.preferences.filter(x=>x!==args.note);else if(action==='listening'){if(!args.key||!args.note?.trim())throw Error('需要歌曲key及实际听感');this.memory.listening.push({key:args.key,note:args.note,selected:args.selected,at:new Date().toISOString()});}else throw Error('未知记忆操作');await this.save();return this.memory;}
 async history(event){await mkdir(this.root,{recursive:true});await appendFile(join(this.root,'listening-history.jsonl'),JSON.stringify({at:new Date().toISOString(),...event})+'\n');}
 async readHistory(offset=0,limit=100){if(!Number.isInteger(offset)||offset<0||!Number.isInteger(limit)||limit<1)throw Error('无效页码参数');let rows=[];try{rows=(await readFile(join(this.root,'listening-history.jsonl'),'utf8')).trim().split('\n').filter(Boolean).map(x=>JSON.parse(x));}catch(e){if(e.code!=='ENOENT')throw e;}return {total:rows.length,offset,records:rows.reverse().slice(offset,offset+limit),note:'本机实际播放事件，不代表整首听完，也不等于模型试听记录。'};}
 wake(agent,text){if(typeof agent?.followup!=='function')throw Error('当前Agent不支持唤醒');return agent.followup({content:[{type:'text',text}],source:{kind:'qian-music'}});}
 setMode(mode,agent){if(!['off','listen','dj','radio'].includes(mode))throw Error('未知陪听模式');if(mode!=='off'&&typeof agent?.followup!=='function')throw Error('需要在DSH会话中调用');this.mode=mode;this.owner=mode==='off'?null:agent;return {mode,note:'仅在DSH运行且本会话可唤醒时有效；off停止后续唤醒。'};}
 async trackStarted(state){this.track={epoch:state.playEpoch,key:state.current?.key,seconds:state.seconds};if(this.mode!=='off'&&this.owner)await this.wake(this.owner,'[千小姐播放器事件] 当前陪听模式 '+this.mode+'；真实开始播放 '+JSON.stringify(state.current)+'。先查询 qian_listening_mode 的当前状态，已停止就不继续。否则原生听当前歌曲；listen/dj可用简短自然的话评价，dj/radio还要实际试听找下一首并qian_queue_add追加，保留当前歌曲。不要把事件元信息当作听过音频。');}
 schedule(args,agent,player){const id=randomUUID(),entry={id,status:'scheduled',...args,epoch:player.state().playEpoch};if(!['track_time','delay','clock','reminder'].includes(args.trigger))throw Error('未知计时类型');if(args.trigger==='reminder'){if(!args.reason?.trim()||typeof agent?.followup!=='function')throw Error('提醒需要原因和当前会话');}else if(!['play','pause','next','previous','volume','mode'].includes(args.action))throw Error('未知播放器定时操作');if(args.at_time&&!/([zZ]|[+-]\d{2}:\d{2})$/.test(args.at_time))throw Error('at_time 必须包含时区');if(args.trigger==='track_time'){if(!player.state().current)throw Error('没有当前歌曲');if(!Number.isFinite(args.seconds)||args.seconds<0)throw Error('无效歌曲秒数');}else{const when=args.at_time?Date.parse(args.at_time):Date.now()+Number(args.seconds)*1000;if(!Number.isFinite(when)||when<Date.now()-1000)throw Error('需要有效的秒数或带时区ISO时间');entry.at=when;}
 entry.run=async()=>{if(entry.status!=='scheduled')return;entry.status='running';try{if(entry.trigger==='reminder')await this.wake(agent,'[千小姐定时提醒] '+args.reason);else await player.control(args.action,args.args||{});entry.status='done';}catch(e){entry.status='failed';entry.error=e.message;}entry.finishedAt=new Date().toISOString();};this.timers.set(id,entry);return this.timerView(entry);}
 timerView(e){const {run,epoch,...view}=e;return view;}
 listTimers(){return [...this.timers.values()].map(e=>this.timerView(e));}
 cancelTimers(id){for(const e of this.timers.values())if((!id||e.id===id)&&e.status==='scheduled')e.status='cancelled';return this.listTimers();}
 tick(state){for(const e of this.timers.values()){if(e.status!=='scheduled')continue;if((e.trigger==='track_time'||e.bind_current_song)&&e.epoch!==state.playEpoch){e.status='cancelled';e.error='当前歌曲已切换或重新播放';continue;}if(e.trigger==='track_time'? !state.paused&&state.seconds>=e.seconds:Date.now()>=e.at)void e.run();}}
 close(){this.mode='off';this.owner=null;this.cancelTimers();}
}
